<script setup lang="ts">import {ref,onMounted} from 'vue';import PageTitle from '../components/common/PageTitle.vue';import Table from '../components/common/Table.vue';import Notice from '../components/common/Notice.vue';import {request} from '../api/client';import {clock} from '../utils/format';const logs=ref<any[]>([]),error=ref('');onMounted(async()=>{try{logs.value=await request('/audit')}catch(e){error.value=e.message}});</script><template><PageTitle index="06" title="观测、版本与核对，都保留来路。" description="最近200条导入、轨迹修订、版本冻结、队列、审批和导出记录。"/><Notice :error="error"/><Table :headers="['时间','操作人','动作','详情']"><tr v-for="l in logs" :key="l.id"><td>{{clock(l.created_at)}}</td><td>{{l.actor}}</td><td>{{l.action}}</td><td>{{JSON.stringify(l.detail)}}</td></tr></Table></template>
